fn choose_num(x: i8, y: i8) -> i8 {
    // If the interval is empty, return -1
    if x > y {
        return -1;
    }

    // Compute the largest even number ≤ y
    let top_even = if y % 2 == 0 { y } else { y - 1 };

    // If that even number is below the lower bound, there's no even in [x, y]
    if top_even < x {
        -1
    } else {
        top_even
    }
}

